package com.shopflow.common.web;

/**
 * Names of the custom HTTP headers that form the contract between the API Gateway and the services.
 *
 * <p>Constants, not magic strings: a typo here is a compile error, not a silent 401 at 2am.
 *
 * <ul>
 *   <li>{@link #CORRELATION_ID} - generated by the gateway if absent, propagated everywhere, echoed on responses.</li>
 *   <li>{@link #USER_ID} / {@link #USER_ROLES} - set by the gateway <em>after</em> it verifies the JWT.
 *       Services must strip any client-supplied copies before trusting these.</li>
 *   <li>{@link #IDEMPOTENCY_KEY} - client-supplied key on unsafe, non-idempotent operations (e.g. create order).</li>
 * </ul>
 */
public final class ShopFlowHeaders {

    private ShopFlowHeaders() {
        // no instances
    }

    public static final String CORRELATION_ID = "X-Correlation-Id";
    public static final String USER_ID = "X-User-Id";
    public static final String USER_ROLES = "X-User-Roles";
    public static final String IDEMPOTENCY_KEY = "Idempotency-Key";
}
